class Solution { public int maximumScore(int[] scores,int[][] edges){int n=scores.length;List<Integer>[] neighbors=new List[n];for(int i=0;i<n;i++)neighbors[i]=new ArrayList<>();for(int[] edge:edges){neighbors[edge[0]].add(edge[1]);neighbors[edge[1]].add(edge[0]);}for(List<Integer> list:neighbors)list.sort((a,b)->Integer.compare(scores[b],scores[a]));int answer=-1;for(int[] edge:edges){int b=edge[0],c=edge[1];for(int ai=0;ai<Math.min(3,neighbors[b].size());ai++)for(int di=0;di<Math.min(3,neighbors[c].size());di++){int a=neighbors[b].get(ai),d=neighbors[c].get(di);if(a!=c&&d!=b&&a!=d)answer=Math.max(answer,scores[a]+scores[b]+scores[c]+scores[d]);}}return answer;} }
